def widest_reservoir(heights):
    i, j = 0, len(heights) - 1
    best = 0
    while i < j:
        h = min(heights[i], heights[j])
        best = max(best, h * (j - i))
        if heights[i] < heights[j]:
            i += 1
        else:
            j -= 1
    return best

