function widest_reservoir(heights) {
  let i = 0;
  let j = heights.length - 1;
  let best = 0;
  while (i < j) {
    const h = Math.min(heights[i], heights[j]);
    best = Math.max(best, h * (j - i));
    if (heights[i] < heights[j]) i++;
    else j--;
  }
  return best;
}

