class Solution {
    public int widestReservoir(int[] heights) {
        int i = 0, j = heights.length - 1;
        int best = 0;
        while (i < j) {
            int h = Math.min(heights[i], heights[j]);
            best = Math.max(best, h * (j - i));
            if (heights[i] < heights[j]) i++;
            else j--;
        }
        return best;
    }
}

